#pragma once

// The pieces that the code generated by Tools/PacketGen uses to read and write the fields of a packet. A
// packet is always read by offset from a span of bytes, never by casting it to a struct (INV-12). The rules
// of the header come from the protocol spec of the knowledge center
// (docs/specs/protocolo/protocolo-106-3-m2.md, section 3).

#include <algorithm>
#include <bit>
#include <cstddef>
#include <cstdint>
#include <span>
#include <string>
#include <string_view>

#include "Nexum/Core/Result.hpp"

namespace mu::protocol {

// The first byte of every message. C1 and C2 travel in the clear; C3 and C4 are encrypted on the wire.
enum class HeaderKind : std::uint8_t { C1 = 0xC1, C2 = 0xC2, C3 = 0xC3, C4 = 0xC4 };

// C1 and C3 keep the length in 1 byte (header of 2 bytes); C2 and C4 in 2 bytes, big-endian (header of 3
// bytes).
[[nodiscard]] constexpr bool HasShortLength(HeaderKind kind) noexcept {
    return kind == HeaderKind::C1 || kind == HeaderKind::C3;
}

[[nodiscard]] constexpr std::size_t HeaderSize(HeaderKind kind) noexcept {
    return HasShortLength(kind) ? 2 : 3;
}

[[nodiscard]] constexpr std::size_t MaximumLength(HeaderKind kind) noexcept {
    return HasShortLength(kind) ? 0xFF : 0xFFFF;
}

// What the generated code knows of a packet before reading it: the bytes that never change and the smallest
// size that holds every field with a fixed place.
struct PacketShape {
    std::string_view name;
    HeaderKind header = HeaderKind::C1;
    std::uint8_t code = 0;
    bool hasSubCode = false;
    std::uint8_t subCode = 0;
    std::size_t minimumLength = 0;
};

// Reading. The generated code only reads below the size it already checked, so these functions do not check
// again.

[[nodiscard]] constexpr std::uint8_t ReadByte(std::span<const std::byte> bytes, std::size_t offset) noexcept {
    return std::to_integer<std::uint8_t>(bytes[offset]);
}

template <typename Value>
[[nodiscard]] constexpr Value ReadLittleEndian(std::span<const std::byte> bytes,
                                               std::size_t offset) noexcept {
    Value value = 0;
    for (std::size_t index = sizeof(Value); index > 0; --index) {
        value = static_cast<Value>((value << 8U) | ReadByte(bytes, offset + index - 1));
    }
    return value;
}

template <typename Value>
[[nodiscard]] constexpr Value ReadBigEndian(std::span<const std::byte> bytes, std::size_t offset) noexcept {
    Value value = 0;
    for (std::size_t index = 0; index < sizeof(Value); ++index) {
        value = static_cast<Value>((value << 8U) | ReadByte(bytes, offset + index));
    }
    return value;
}

// A field of `length` bits that starts `shift` bits above the lowest bit of the value.
template <typename Value>
[[nodiscard]] constexpr Value TakeBits(Value value, unsigned shift, unsigned length) noexcept {
    const auto mask = static_cast<Value>((1U << length) - 1U);
    return static_cast<Value>((value >> shift) & mask);
}

template <typename Value>
[[nodiscard]] constexpr Value PutBits(Value value, unsigned shift, unsigned length, Value field) noexcept {
    const auto mask = static_cast<Value>(((1U << length) - 1U) << shift);
    return static_cast<Value>((value & static_cast<Value>(~mask)) |
                              (static_cast<Value>(field << shift) & mask));
}

[[nodiscard]] inline float ReadFloat(std::span<const std::byte> bytes, std::size_t offset) noexcept {
    return std::bit_cast<float>(ReadLittleEndian<std::uint32_t>(bytes, offset));
}

[[nodiscard]] inline double ReadDouble(std::span<const std::byte> bytes, std::size_t offset) noexcept {
    return std::bit_cast<double>(ReadLittleEndian<std::uint64_t>(bytes, offset));
}

// Writing. As with reading, the generated code only writes below the size of the buffer it was given.

constexpr void WriteByte(std::span<std::byte> bytes, std::size_t offset, std::uint8_t value) noexcept {
    bytes[offset] = std::byte{value};
}

template <typename Value>
constexpr void WriteLittleEndian(std::span<std::byte> bytes, std::size_t offset, Value value) noexcept {
    for (std::size_t index = 0; index < sizeof(Value); ++index) {
        WriteByte(bytes, offset + index, static_cast<std::uint8_t>(value >> (8U * index)));
    }
}

template <typename Value>
constexpr void WriteBigEndian(std::span<std::byte> bytes, std::size_t offset, Value value) noexcept {
    for (std::size_t index = 0; index < sizeof(Value); ++index) {
        WriteByte(bytes, offset + index,
                  static_cast<std::uint8_t>(value >> (8U * (sizeof(Value) - 1 - index))));
    }
}

inline void WriteFloat(std::span<std::byte> bytes, std::size_t offset, float value) noexcept {
    WriteLittleEndian(bytes, offset, std::bit_cast<std::uint32_t>(value));
}

inline void WriteDouble(std::span<std::byte> bytes, std::size_t offset, double value) noexcept {
    WriteLittleEndian(bytes, offset, std::bit_cast<std::uint64_t>(value));
}

// A text field: UTF-8, ending at the first zero or at the end of the field.
class PacketText {
public:
    explicit constexpr PacketText(std::span<const std::byte> field) noexcept
        : m_bytes(field.first(static_cast<std::size_t>(std::find(field.begin(), field.end(), std::byte{0}) -
                                                       field.begin()))) {}

    [[nodiscard]] constexpr std::size_t size() const noexcept { return m_bytes.size(); }
    [[nodiscard]] constexpr bool empty() const noexcept { return m_bytes.empty(); }
    [[nodiscard]] constexpr std::span<const std::byte> Bytes() const noexcept { return m_bytes; }

    [[nodiscard]] constexpr bool Equals(std::string_view text) const noexcept {
        return std::equal(m_bytes.begin(), m_bytes.end(), text.begin(), text.end(),
                          [](std::byte byte, char letter) { return byte == static_cast<std::byte>(letter); });
    }

    // Copies the text; it asks for memory, so it is meant for the log and for the tests, not for every frame.
    [[nodiscard]] std::string ToString() const {
        std::string text(m_bytes.size(), '\0');
        std::transform(m_bytes.begin(), m_bytes.end(), text.begin(),
                       [](std::byte byte) { return static_cast<char>(byte); });
        return text;
    }

private:
    std::span<const std::byte> m_bytes;
};

// Writes the text and fills the rest of the field with zeros. A text longer than the field is refused, so
// nothing is cut without a word.
[[nodiscard]] nexum::core::Result<void> WriteText(std::span<std::byte> field, std::string_view text);

// Copies the bytes to the start of the field and fills the rest with zeros. Bytes longer than the field are
// refused.
[[nodiscard]] nexum::core::Result<void> WriteBinary(std::span<std::byte> field,
                                                    std::span<const std::byte> bytes);

// The length that the header of the message declares. The message must hold its whole header.
[[nodiscard]] std::size_t DeclaredLength(std::span<const std::byte> message) noexcept;

// Checks that the bytes are a whole message of this shape: the header, the code, the subcode and the smallest
// size. C1 and C3 (and C2 and C4) are accepted for each other, because the encryption only changes the first
// byte on the wire, and after decryption the first byte still says C3 or C4.
[[nodiscard]] nexum::core::Result<void> CheckPacket(std::span<const std::byte> message,
                                                    const PacketShape& shape);

// Starts a message of this shape in the buffer: zeros everywhere, then the header, the length (the size of
// the buffer), the code and the subcode.
[[nodiscard]] nexum::core::Result<void> StartPacket(std::span<std::byte> buffer, const PacketShape& shape);

// Checks that a structure of a packet fits in the bytes that are left.
[[nodiscard]] nexum::core::Result<void> CheckStructure(std::span<const std::byte> bytes,
                                                       std::string_view name, std::size_t size);

} // namespace mu::protocol
